const TTL = 24 * 60 * 60 * 1000; // sessions expire after 24 hours of silence
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const loadSession = (chatId) => {
  const s = sd.sessions[String(chatId)];
  return (s && Date.now() - (s.updatedAt || 0) < TTL) ? s : {};
};
const saveSession = (chatId, s) => { s.updatedAt = Date.now(); sd.sessions[String(chatId)] = s; };

const u = $input.first().json;
const now = Date.now();

// housekeeping: keep the stored sessions list small
const keys = Object.keys(sd.sessions);
if (keys.length > 1000) {
  keys.sort((a, b) => (sd.sessions[a].updatedAt || 0) - (sd.sessions[b].updatedAt || 0))
      .slice(0, keys.length - 900).forEach(k => delete sd.sessions[k]);
}

let kind = 'unsupported';
let chatId = null, firstName = 'there', text = '', lat = null, lon = null;
let callbackData = '', queryId = '', reply = '';
const NON_TEXT = "I can read text messages and shared locations 😊\n\nSend me a city name or ask a weather question, like: \"Will it rain in Lagos tomorrow?\"";

const cb = u.callback_query;
const msg = u.message;

if (cb) {
  chatId = cb.message?.chat?.id ?? cb.from?.id ?? null;
  firstName = cb.from?.first_name || 'there';
  callbackData = String(cb.data || '').slice(0, 64);
  queryId = cb.id || '';
  kind = 'callback';
} else if (msg) {
  chatId = msg.chat?.id ?? null;
  firstName = msg.from?.first_name || 'there';
  if (msg.location) {
    lat = typeof msg.location.latitude === 'number' ? msg.location.latitude : null;
    lon = typeof msg.location.longitude === 'number' ? msg.location.longitude : null;
    kind = 'location';
  } else if (typeof msg.text === 'string') {
    text = msg.text.trim();
    if (text === '') {
      reply = NON_TEXT;
    } else if (text.length > 300) {
      reply = "😅 That message is a bit long for me.\n\nPlease keep it short, for example: \"Weather in Lagos\".";
    } else if (text.startsWith('/')) {
      const cmd = text.split(/[\s@]/)[0].toLowerCase();
      if (cmd === '/start') kind = 'start';
      else if (cmd === '/help') kind = 'help';
      else reply = "🤔 I don't know that command.\n\nTry /start or /help, or just send me a city name.";
    } else {
      kind = 'text';
    }
  } else {
    reply = NON_TEXT;
  }
}

if (chatId === null || chatId === undefined) return [];

const session = loadSession(chatId);

// A button asked for a city and the next message looks like a bare city name
if (kind === 'text' && session.pending) {
  const cityLike = /^[\p{L}\p{M}'’.\- ,]+$/u.test(text) && text.split(/\s+/).length <= 5 &&
    !/\b(what|will|is|are|how|should|can|compare|weather|rain|umbrella|tomorrow|today|forecast|hotter|colder|temperature|about|thanks|thank|hi|hello|hey)\b/i.test(text);
  if (cityLike) kind = 'pending_city';
}

return [{ json: { kind, chatId, firstName, text, lat, lon, callbackData, queryId, reply, session, withMenu: true } }];

const TTL = 24 * 60 * 60 * 1000; // sessions expire after 24 hours of silence
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const loadSession = (chatId) => {
  const s = sd.sessions[String(chatId)];
  return (s && Date.now() - (s.updatedAt || 0) < TTL) ? s : {};
};
const saveSession = (chatId, s) => { s.updatedAt = Date.now(); sd.sessions[String(chatId)] = s; };

const helpText = `❓ WEATHER BUDDY HELP\n\nHere's what I can do:\n🌤️ Current weather: "Weather in Lagos"\n📅 Forecasts: "Tomorrow in Abuja" or "Next 3 days in Kano" (up to 15 days ahead)\n🌧️ Rain checks: "Will I need an umbrella in Port Harcourt tomorrow?"\n🔀 Comparisons: "Is Lagos hotter than Port Harcourt?"\n💬 Follow-ups: after a city, just ask "What about tomorrow?"\n📍 Location: tap 📎, choose Location, and send it (optional)\n\nTips:\n• Add the country when a name is shared (London, Canada).\n• For a Nigerian state, send the state name or its capital.\n• I remember the last place you checked for up to 24 hours so follow-ups work.\n\nCommands: /start /help`;

const { chatId, callbackData } = $input.first().json;
const s = loadSession(chatId);
const setPending = (p) => { s.pending = p; saveSession(chatId, s); };
let reply = '';
let withMenu = false;

switch (callbackData) {
  case 'cb:current':
    setPending({ intent: 'current', dateSpec: { type: 'relative', offset: 0 } });
    reply = '🌤️ Sure! Which city should I check?\n\nType a city name (like Lagos, Nigeria) or share your location.';
    break;
  case 'cb:tomorrow':
    setPending({ intent: 'forecast', dateSpec: { type: 'relative', offset: 1 } });
    reply = "📅 Happy to! Which city's forecast for tomorrow?\n\nType a city name (like Abuja) or share your location.";
    break;
  case 'cb:rain':
    setPending({ intent: 'rain', dateSpec: { type: 'relative', offset: 0 } });
    reply = '🌧️ Let me check the rain chances. Which city?\n\nType a city name (like Port Harcourt) or share your location.';
    break;
  case 'cb:location':
    reply = "📍 To share your location, tap the 📎 attachment icon in Telegram, choose Location, and send your current location.\n\nSharing is optional. I only use the coordinates to look up the weather, and I keep the last place for up to 24 hours so follow-up questions work.";
    break;
  case 'cb:help':
    reply = helpText;
    withMenu = true;
    break;
  default:
    reply = "Hmm, that button isn't active any more 🤔\n\nHere's the menu again:";
    withMenu = true;
}
return [{ json: { chatId, reply, withMenu } }];

const ctx = $input.first().json;
let { lat, lon } = ctx;
const ok = Number.isFinite(lat) && Number.isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
if (!ok) {
  return [{ json: { action: 'reply', chatId: ctx.chatId, reply: "📍 I couldn't read that location.\n\nPlease try sharing it again, or just send me a city name.", withMenu: true } }];
}
// round to ~1 km before sending to Open-Meteo or storing in the session
lat = Math.round(lat * 100) / 100;
lon = Math.round(lon * 100) / 100;
const p = (ctx.session && ctx.session.pending) || { intent: 'current', dateSpec: { type: 'relative', offset: 0 } };
const dateSpec = p.dateSpec || { type: 'relative', offset: 0 };
const days = Math.max(1, Math.min(7, parseInt(p.days, 10) || 1));
return [{ json: {
  action: 'weather', chatId: ctx.chatId, firstName: ctx.firstName,
  intent: p.intent || 'current', dateSpec, days, forecastDays: Math.min(16, dateSpec.offset + days),
  targetIndex: 0, targetCount: 1,
  loc: { label: 'Your shared location', lat, lon }
} }];

// Nigerian states whose own name does not geocode to the right place -> capital city
const stateCapitals = {
  'abia': 'Umuahia', 'adamawa': 'Yola', 'akwa ibom': 'Uyo', 'anambra': 'Awka',
  'benue': 'Makurdi', 'borno': 'Maiduguri', 'cross river': 'Calabar', 'delta': 'Asaba',
  'ebonyi': 'Abakaliki', 'edo': 'Benin City', 'ekiti': 'Ado-Ekiti', 'imo': 'Owerri',
  'kebbi': 'Birnin Kebbi', 'kogi': 'Lokoja', 'kwara': 'Ilorin', 'niger': 'Minna',
  'ogun': 'Abeokuta', 'osun': 'Osogbo', 'plateau': 'Jos', 'rivers': 'Port Harcourt',
  'taraba': 'Jalingo', 'yobe': 'Damaturu', 'zamfara': 'Gusau', 'jigawa': 'Dutse', 'fct': 'Abuja'
};
function parseLocation(raw) {
  const parts = String(raw || '').split(',');
  let city = parts[0].trim();
  let hint = parts.slice(1).join(',').trim().toLowerCase();
  const key = city.toLowerCase().replace(/\s+state$/, '');
  if ((hint === '' || hint === 'nigeria' || hint === 'ng') && stateCapitals[key]) {
    city = stateCapitals[key];
