const ctx = $('Normalize Update').first().json;
const g = $input.first().json;
const session = ctx.session || {};
const name = ctx.firstName || 'there';
const reply = (text, menu = true) => [{ json: { action: 'reply', chatId: ctx.chatId, reply: text, withMenu: menu } }];

// 1. Parse the model output safely
let parsed = null;
try {
  const raw = (g.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) { parsed = null; }

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  console.log('[WeatherBuddy] Gemini output unusable:', JSON.stringify(g).slice(0, 400));
  const t = String(ctx.text || '');
  const looksLikeCity = t.length <= 40 && t.split(/\s+/).length <= 4 && !/[?!]/.test(t);
  if (!looksLikeCity) {
    return reply("😅 I'm having a little trouble understanding that right now.\n\nTry sending just a city name, like Lagos, Nigeria.");
  }
  parsed = { intent: 'current', locations: [t], date: null, days: 1, use_previous_location: false };
}

// 2. Validate intent
const intents = ['current', 'forecast', 'rain', 'compare', 'greeting', 'thanks', 'help', 'other'];
let intent = intents.includes(parsed.intent) ? parsed.intent : 'other';
const clarif = typeof parsed.clarification_question === 'string' ? parsed.clarification_question.trim().slice(0, 200) : '';

if (intent === 'greeting') return reply(`Hey ${name}! 😊 Which city would you like me to check?\n\nExample: Lagos, Nigeria`);
if (intent === 'thanks') return reply(`You're welcome, ${name}! 😊\n\nI'll be here whenever you need Weather Buddy. And if rain is on the way, I'll remind you to carry an umbrella ☔`);
if (intent === 'help') return reply('Send /help to see everything I can do 😊');
if (intent === 'other') {
  return reply(clarif || "🤔 I can help with current weather, forecasts, rain checks, and comparing cities.\n\nTry: \"Will it rain in Abuja tomorrow?\"");
}

// 3. Validate date
const todayLagos = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Lagos' });
let dateSpec = { type: 'relative', offset: 0 };
const d = typeof parsed.date === 'string' ? parsed.date.trim().toLowerCase() : null;
if (d === 'tomorrow') {
  dateSpec = { type: 'relative', offset: 1 };
} else if (d && /^\d{4}-\d{2}-\d{2}$/.test(d)) {
  const diff = Math.round((Date.parse(d + 'T00:00:00Z') - Date.parse(todayLagos + 'T00:00:00Z')) / 86400000);
  if (!Number.isFinite(diff) || diff < 0) {
    return reply("📅 I can only look at today and upcoming days.\n\nTry asking about today, tomorrow, or a date in the next two weeks.");
  }
  if (diff > 15) {
    return reply("📅 I can forecast up to 15 days ahead.\n\nTry a date within the next two weeks.");
  }
  dateSpec = { type: 'date', iso: d, offset: diff };
}

let days = parseInt(parsed.days, 10);
if (!Number.isFinite(days) || days < 1) days = 1;
days = Math.min(days, 7);
if (intent === 'current' || intent === 'compare') days = 1;
if (intent === 'current' && dateSpec.offset > 0) intent = 'forecast';
if (dateSpec.offset + days > 16) days = Math.max(1, 16 - dateSpec.offset);
const forecastDays = Math.min(16, dateSpec.offset + days);

// 4. Validate locations
const locations = (Array.isArray(parsed.locations) ? parsed.locations : [])
  .filter(x => typeof x === 'string' && x.trim() !== '')
  .map(x => x.trim().slice(0, 80)).slice(0, 3);
const prev = session.lastLocation;
let targets = [];

if (locations.length === 0) {
  if (prev && Number.isFinite(prev.lat) && Number.isFinite(prev.lon)) {
    targets = [{ loc: { label: prev.label, query: prev.query || null, lat: prev.lat, lon: prev.lon } }];
  } else {
    // remember what was asked, so the next bare city name completes this request
    const s0 = loadSession(ctx.chatId);
    s0.pending = { intent, dateSpec, days };
    saveSession(ctx.chatId, s0);
    return reply(clarif || '📍 Which city should I check?\n\nExample: Lagos, Nigeria', false);
  }
} else {
  targets = locations.map(l => ({ geo: parseLocation(l) }));
  if (intent === 'compare' && targets.length === 1 && prev && prev.query) {
    targets.unshift({ geo: parseLocation(prev.query) });
  }
}

if (intent === 'compare' && targets.length < 2) {
  return reply('🔀 Which two cities would you like me to compare?\n\nExample: Lagos and Port Harcourt', false);
}

return targets.map((t, i) => ({ json: {
  action: 'weather', chatId: ctx.chatId, firstName: name,
  intent, dateSpec, days, forecastDays, targetIndex: i, targetCount: targets.length,
  ...t
} }));

const reqs = $('Geocode Request').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const chatId = reqs[0].chatId;
const reply = (t, menu = true) => [{ json: { action: 'reply', chatId, reply: t, withMenu: menu } }];

const alias = { uk: 'gb', usa: 'us', 'u.s.a.': 'us', 'u.s.': 'us', uae: 'ae' };
const norm = (v) => String(v || '').toLowerCase().replace(/\s+state$/, '').trim();
const normHint = (v) => { const n = norm(v); return alias[n] || n; };
const matches = (r, p) => norm(r.country) === p || norm(r.country_code) === p ||
  norm(r.admin1) === p || norm(r.admin2) === p || norm(r.country).startsWith(p);
const optionLabel = (r) => [r.name, r.admin1 && norm(r.admin1) !== norm(r.name) ? r.admin1 : null, r.country].filter(Boolean).join(', ');

if (res.length !== reqs.length) {
  console.log('[WeatherBuddy] Geocoding returned', res.length, 'items for', reqs.length, 'requests');
  return reply("⚠️ Sorry, I couldn't look that place up right now.\n\nPlease try again shortly.");
}

const resolved = [];
for (let i = 0; i < reqs.length; i++) {
  const { city, hint } = reqs[i].geo;
  const r = res[i] || {};

  // Technical failure (HTTP error / unexpected body) is different from "no match"
  if (r.error || (!Array.isArray(r.results) && typeof r.generationtime_ms !== 'number')) {
    console.log('[WeatherBuddy] Geocoding failure for', JSON.stringify(city), JSON.stringify(r).slice(0, 300));
    return reply("⚠️ Sorry, I couldn't look that place up right now.\n\nPlease try again shortly.");
  }

  const results = Array.isArray(r.results) ? r.results : [];
  const hintParts = hint ? hint.split(',').map(normHint).filter(Boolean) : [];
  const pool = hintParts.length ? results.filter(x => hintParts.every(p => matches(x, p))) : results;

  if (pool.length === 0) {
    return reply(`❌ I couldn't find "${city}".\n\nPlease check the spelling or add the country, for example: Lagos, Nigeria.`);
  }

  const top = pool[0];
  if (!hintParts.length) {
    const topPop = top.population || 0;
    const rivals = pool.slice(1).filter(x => norm(x.name) === norm(top.name) &&
      (x.country_code !== top.country_code || norm(x.admin1) !== norm(top.admin1)));
    const serious = rivals.filter(x => topPop === 0 ? true : (x.population || 0) >= 0.25 * topPop);
    if (serious.length > 0) {
      const options = [top, ...serious].slice(0, 3);
      const second = options[1];
      const example = `${second.name}, ${second.country_code === top.country_code ? (second.admin1 || second.country) : second.country}`;
      const list = options.map((o, k) => `${k + 1}. ${optionLabel(o)}`).join('\n');
      return reply(`🤔 I found a few places called ${top.name}:\n\n${list}\n\nWhich one did you mean? Send the name with the country or state, for example: ${example}`, false);
    }
  }

  resolved.push({
    label: optionLabel(top), lat: top.latitude, lon: top.longitude,
    timezone: top.timezone || '', query: `${top.name}, ${top.country_code || ''}`.replace(/,\s*$/, '')
  });
}

return resolved.map((loc, i) => ({ json: {
  action: 'weather', chatId, firstName: reqs[i].firstName, intent: reqs[i].intent,
  dateSpec: reqs[i].dateSpec, days: reqs[i].days, forecastDays: reqs[i].forecastDays,
  targetIndex: i, targetCount: resolved.length, loc
} }));

const TTL = 24 * 60 * 60 * 1000; // sessions expire after 24 hours of silence
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const loadSession = (chatId) => {
  const s = sd.sessions[String(chatId)];
  return (s && Date.now() - (s.updatedAt || 0) < TTL) ? s : {};
};
const saveSession = (chatId, s) => { s.updatedAt = Date.now(); sd.sessions[String(chatId)] = s; };

const reqs = $('Weather Request').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const first = reqs[0];
const { chatId, intent, dateSpec, days } = first;
const out = (text) => [{ json: { chatId, reply: String(text).slice(0, 3900), withMenu: true } }];

const has = (v) => typeof v === 'number' && Number.isFinite(v);
const r1 = (n) => Math.round(n * 10) / 10;
const valid = (w) => w && !w.error && w.current && has(w.current.temperature_2m) &&
  w.daily && Array.isArray(w.daily.time) && w.daily.time.length > 0;

if (res.length !== reqs.length || !res.every(valid)) {
  console.log('[WeatherBuddy] Weather API problem:', JSON.stringify(res.map(r => (r && r.error) ? r.error : 'unexpected response')).slice(0, 600));
  return out("⚠️ Sorry, I couldn't retrieve the weather right now.\n\nPlease try again shortly.");
}

// WMO weather interpretation codes -> [emoji, description]
const WMO = {
  0: ['☀️', 'Clear sky'], 1: ['🌤️', 'Mainly clear'], 2: ['⛅', 'Partly cloudy'], 3: ['☁️', 'Overcast'],
  45: ['🌫️', 'Fog'], 48: ['🌫️', 'Depositing rime fog'],
  51: ['🌦️', 'Light drizzle'], 53: ['🌦️', 'Moderate drizzle'], 55: ['🌦️', 'Dense drizzle'],
  56: ['🌧️', 'Light freezing drizzle'], 57: ['🌧️', 'Dense freezing drizzle'],
  61: ['🌧️', 'Slight rain'], 63: ['🌧️', 'Moderate rain'], 65: ['🌧️', 'Heavy rain'],
  66: ['🌧️', 'Light freezing rain'], 67: ['🌧️', 'Heavy freezing rain'],
  71: ['🌨️', 'Slight snowfall'], 73: ['🌨️', 'Moderate snowfall'], 75: ['❄️', 'Heavy snowfall'], 77: ['❄️', 'Snow grains'],
  80: ['🌦️', 'Slight rain showers'], 81: ['🌧️', 'Moderate rain showers'], 82: ['⛈️', 'Violent rain showers'],
  85: ['🌨️', 'Slight snow showers'], 86: ['❄️', 'Heavy snow showers'],
  95: ['⛈️', 'Thunderstorm'], 96: ['⛈️', 'Thunderstorm with slight hail'], 99: ['⛈️', 'Thunderstorm with heavy hail']
};
const wmo = (c) => WMO[c] || ['🌡️', 'Unknown conditions'];
const RAIN_CODES = [51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99];

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const fmtDate = (iso) => {
  const d = new Date(iso + 'T00:00:00Z');
  return `${WEEKDAYS[d.getUTCDay()]} ${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`;
};
const fmtTime = (t) => {
  const [dd, tt] = String(t).split('T');
  const [, mm, day] = dd.split('-');
  return `${parseInt(day, 10)} ${MONTHS[parseInt(mm, 10) - 1]}, ${tt}`;
};
const dayLabel = (w, i) => i === 0 ? 'Today' : i === 1 ? 'Tomorrow' : fmtDate(w.daily.time[i]);
const idxFor = (w) => dateSpec.type === 'date' ? w.daily.time.indexOf(dateSpec.iso) : dateSpec.offset;

const useDaily = intent === 'forecast' || intent === 'rain' ||
  (intent === 'compare' && (dateSpec.offset > 0 || dateSpec.type === 'date'));

if (useDaily) {
  for (const w of res) {
    const i0 = idxFor(w);
    if (i0 < 0 || i0 + days > w.daily.time.length) {
      return out("📅 I can only forecast up to 15 days ahead.\n\nTry asking about today, tomorrow, or a date in the next two weeks.");
    }
  }
}

const adviceFor = (prob, psum, code) => {
  const rainy = RAIN_CODES.includes(code);
  if ((has(prob) && prob >= 60) || (has(psum) && psum >= 5) || (!has(prob) && rainy)) return '☔ Yes, carry an umbrella.';
  if (has(prob) && prob >= 30) return '🌂 Showers are possible, so a small umbrella is a good idea.';
  if (!has(prob) && !has(psum)) return "I don't have rain data for that day.";
  return "😎 Rain looks unlikely, so you probably won't need an umbrella.";
};

const currentBlock = (req, w) => {
  const c = w.current;
  const [icon, desc] = wmo(c.weather_code);
  const lines = [`${icon} Weather in ${req.loc.label}`, ''];
  lines.push(`🌡️ Temperature: ${r1(c.temperature_2m)}°C` + (has(c.apparent_temperature) ? ` (feels like ${r1(c.apparent_temperature)}°C)` : ''));
  lines.push(`🌥️ Condition: ${desc}`);
  if (has(c.relative_humidity_2m)) lines.push(`💧 Humidity: ${Math.round(c.relative_humidity_2m)}%`);
  if (has(c.wind_speed_10m)) lines.push(`💨 Wind: ${r1(c.wind_speed_10m)} km/h`);
  if (has(c.precipitation)) lines.push(`🌧️ Precipitation now: ${r1(c.precipitation)} mm`);
  const p0 = w.daily.precipitation_probability_max ? w.daily.precipitation_probability_max[0] : null;
  if (has(p0)) lines.push(`☔ Chance of rain today: ${Math.round(p0)}%`);
  if (c.time) lines.push(`🕒 Local time: ${fmtTime(c.time)}`);
  const raining = RAIN_CODES.includes(c.weather_code) || (has(c.precipitation) && c.precipitation > 0);
  if (raining) lines.push('', '☔ It is raining, so please carry an umbrella!');
  else if (has(p0) && p0 >= 60) lines.push('', '🌂 Rain is likely later today, so keep an umbrella handy.');
  return lines.join('\n');
};

const dayLine = (w, i) => {
  const code = w.daily.weather_code ? w.daily.weather_code[i] : undefined;
  const [icon, desc] = wmo(code);
  const tmax = w.daily.temperature_2m_max ? w.daily.temperature_2m_max[i] : undefined;
  const tmin = w.daily.temperature_2m_min ? w.daily.temperature_2m_min[i] : undefined;
  const prob = w.daily.precipitation_probability_max ? w.daily.precipitation_probability_max[i] : undefined;
  const psum = w.daily.precipitation_sum ? w.daily.precipitation_sum[i] : undefined;
  const wind = w.daily.wind_speed_10m_max ? w.daily.wind_speed_10m_max[i] : undefined;
  const bits = [];
  if (has(tmin) && has(tmax)) bits.push(`🌡️ ${r1(tmin)} to ${r1(tmax)}°C`);
  if (has(prob)) bits.push(`☔ ${Math.round(prob)}% chance of rain`);
  if (has(psum)) bits.push(`🌧️ ${r1(psum)} mm`);
  if (has(wind)) bits.push(`💨 up to ${r1(wind)} km/h`);
  return `${dayLabel(w, i)}: ${icon} ${desc}` + (bits.length ? '\n   ' + bits.join(' · ') : '');
};

const forecastBlock = (req, w) => {
  const i0 = idxFor(w);
  const lines = [`📅 Forecast for ${req.loc.label}`, ''];
  for (let k = 0; k < days; k++) lines.push(dayLine(w, i0 + k));
  return lines.join('\n');
};

const rainBlock = (req, w) => {
  const i0 = idxFor(w);
  const lines = [`🌧️ Rain check for ${req.loc.label}`, ''];
  let worst = null;
  for (let k = 0; k < days; k++) {
    const i = i0 + k;
    const prob = w.daily.precipitation_probability_max ? w.daily.precipitation_probability_max[i] : undefined;
    const psum = w.daily.precipitation_sum ? w.daily.precipitation_sum[i] : undefined;
    const code = w.daily.weather_code ? w.daily.weather_code[i] : undefined;
    const [icon, desc] = wmo(code);
    const bits = [];
    if (has(prob)) bits.push(`${Math.round(prob)}% chance`);
    if (has(psum)) bits.push(`${r1(psum)} mm`);
    lines.push(`${dayLabel(w, i)}: ${icon} ${desc}` + (bits.length ? ' - ' + bits.join(', ') : ''));
    const score = has(prob) ? prob : 0;
    if (!worst || score > worst.score) worst = { i, prob, psum, code, score };
  }
  lines.push('', adviceFor(worst.prob, worst.psum, worst.code) + (days > 1 ? ` (highest risk: ${dayLabel(w, worst.i)})` : ''));
  lines.push('Forecasts can change, so check again if your plans depend on it.');
  return lines.join('\n');
};

const compareBlock = () => {
  const rows = reqs.map((req, k) => {
    const w = res[k];
    if (useDaily) {
      const i = idxFor(w);
      const [icon, desc] = wmo(w.daily.weather_code ? w.daily.weather_code[i] : undefined);
      return { label: req.loc.label, temp: w.daily.temperature_2m_max ? w.daily.temperature_2m_max[i] : undefined, icon, desc };
    }
    const [icon, desc] = wmo(w.current.weather_code);
    return { label: req.loc.label, temp: w.current.temperature_2m, icon, desc };
  });
  if (rows.some(r => !has(r.temp))) return null;
  const when = useDaily ? `expected highs for ${dayLabel(res[0], idxFor(res[0]))}` : 'right now';
  const lines = [`🔀 Comparison, ${when}`, ''];
  rows.forEach(r => lines.push(`${r.icon} ${r.label}: ${r1(r.temp)}°C, ${r.desc}`));
  const sorted = [...rows].sort((a, b) => b.temp - a.temp);
  const top = sorted[0], bottom = sorted[sorted.length - 1];
  lines.push('');
  if (top.temp - bottom.temp < 0.5) lines.push('🌡️ The temperatures are about the same.');
  else if (rows.length === 2) lines.push(`🔥 ${top.label} is warmer than ${bottom.label} by ${r1(top.temp - bottom.temp)}°C.`);
  else lines.push(`🔥 Warmest: ${top.label} (${r1(top.temp)}°C)\n❄️ Coolest: ${bottom.label} (${r1(bottom.temp)}°C)`);
  return lines.join('\n');
};

let blocks;
if (intent === 'compare') {
  const b = compareBlock();
  if (!b) {
    console.log('[WeatherBuddy] Compare failed: missing temperature values');
    return out("⚠️ Sorry, I couldn't retrieve the weather right now.\n\nPlease try again shortly.");
  }
  blocks = [b];
} else {
  blocks = reqs.map((req, k) => intent === 'rain' ? rainBlock(req, res[k]) : intent === 'forecast' ? forecastBlock(req, res[k]) : currentBlock(req, res[k]));
}

// Basic memory: remember the last place and intent for follow-up questions (production runs only)
const s = loadSession(chatId);
const l0 = reqs[0].loc;
s.lastLocation = { label: l0.label, query: l0.query || null, lat: l0.lat, lon: l0.lon };
s.lastIntent = intent;
s.pending = null;
saveSession(chatId, s);

return out(blocks.join('\n\n') + '\n\n🌐 Weather data provided by Open-Meteo.com');
